"""Integration tests for F100: Generated files include 'DO NOT EDIT' warning header.

Test Requirements:
- test_python_has_header - Python files have warning header
- test_dart_has_header - Dart files have warning header
- test_docker_has_header - Docker files have warning header
- test_header_mentions_auto_generated - header says auto-generated
"""

import tempfile
import os
from pathlib import Path
import pytest

from schnitzel.schema.models import SchnitzelSchema, Model, FieldDefinition
from schnitzel.generators.python import PythonModelGenerator
from schnitzel.generators.dart import DartModelGenerator
from schnitzel.generators.docker.compose import DockerComposeGenerator


@pytest.fixture
def temp_dir():
    """Create a temporary directory for testing and change to it."""
    original_cwd = os.getcwd()
    with tempfile.TemporaryDirectory() as tmpdir:
        os.chdir(tmpdir)
        yield Path(tmpdir)
        os.chdir(original_cwd)


@pytest.fixture
def sample_schema():
    """Create a simple schema for testing."""
    return SchnitzelSchema(
        models={
            "User": Model(
                name="User",
                description="A user in the system",
                fields={
                    "id": FieldDefinition(type="uuid", primary=True),
                    "name": FieldDefinition(type="string"),
                    "email": FieldDefinition(type="string"),
                }
            )
        }
    )


def test_python_has_header(temp_dir: Path, sample_schema: SchnitzelSchema) -> None:
    """Test that Python generated files have a DO NOT EDIT warning header."""
    # Generate Python models
    generator = PythonModelGenerator()
    output_file, _ = generator.generate_to_file(
        sample_schema,
        temp_dir / "python",
        schema_source="test_schema.yaml"
    )

    # Read the generated file
    content = output_file.read_text(encoding="utf-8")

    # Verify header exists at the top of the file
    lines = content.split("\n")

    # First line should be a comment with "Generated by Schnitzel"
    assert lines[0].startswith("#"), "First line should be a comment"
    assert "Generated by Schnitzel" in lines[0], "Header should mention Schnitzel Framework"

    # Should have DO NOT EDIT warning
    header_text = "\n".join(lines[:10])  # Check first 10 lines
    assert "DO NOT EDIT" in header_text, "Header should contain 'DO NOT EDIT' warning"


