def test_python_header_before_imports(temp_dir: Path, sample_schema: SchnitzelSchema) -> None:
    """Test that Python header appears before any import statements."""
    generator = PythonModelGenerator()
    output_file, _ = generator.generate_to_file(
        sample_schema,
        temp_dir / "python",
        schema_source="test_schema.yaml"
    )

    content = output_file.read_text(encoding="utf-8")
    lines = content.split("\n")

    # Find first import line
    first_import_index = None
    for i, line in enumerate(lines):
        if line.startswith("from ") or line.startswith("import "):
            first_import_index = i
            break

    assert first_import_index is not None, "Should have import statements"

    # Verify header comes before imports
    header_found = False
    for i in range(first_import_index):
        if "DO NOT EDIT" in lines[i]:
            header_found = True
            break

    assert header_found, "DO NOT EDIT header should appear before imports"


